create type public.import_status as enum ('uploaded','reviewed','committed','failed');
create table public.imports (id uuid primary key default gen_random_uuid(),trip_id uuid references public.trips(id) on delete set null,owner_id uuid not null references public.profiles(id),file_name text not null,file_type text not null check(file_type in ('csv','json')),sha256 text not null,raw_payload jsonb not null,mapping_payload jsonb not null default '{}'::jsonb,warnings jsonb not null default '[]'::jsonb,status public.import_status not null default 'uploaded',error_code text,created_at timestamptz not null default now(),unique(owner_id,sha256));
create table public.rule_snapshots (id uuid primary key default gen_random_uuid(),rule_key text not null,provider text not null,title text not null,description text not null,applicable_from date,applicable_through date,verified_at date not null,source_url text not null,source_hash text,logic_version text not null,parameters jsonb not null default '{}'::jsonb,active boolean not null default true,created_at timestamptz not null default now());
create table public.booking_windows (id uuid primary key default gen_random_uuid(),trip_id uuid not null references public.trips(id) on delete cascade,kind text not null,opens_at timestamptz not null,timezone text not null,status public.plan_status not null default 'planned',notes text,source_url text not null,verified_at date not null,reminder_sent_at timestamptz,created_at timestamptz not null default now());
create table public.conflicts (id uuid primary key default gen_random_uuid(),trip_id uuid not null references public.trips(id) on delete cascade,day_id uuid references public.days(id) on delete set null,event_id uuid references public.events(id) on delete set null,rule_snapshot_id uuid not null references public.rule_snapshots(id),dedupe_key text not null,severity public.conflict_severity not null,status public.conflict_status not null default 'open',title text not null,reason text not null,recommended_action text not null,resolution_note text,detected_at timestamptz not null default now(),unique(trip_id,dedupe_key,rule_snapshot_id));
create table public.audit_events (id bigint generated always as identity primary key,trip_id uuid not null references public.trips(id) on delete cascade,actor_id uuid references public.profiles(id),entity_type text not null,entity_id uuid,action text not null,before jsonb,after jsonb,created_at timestamptz not null default now());
alter table public.imports enable row level security; alter table public.rule_snapshots enable row level security; alter table public.booking_windows enable row level security; alter table public.conflicts enable row level security; alter table public.audit_events enable row level security;
create policy "imports owner read" on public.imports for select using(owner_id=auth.uid());create policy "imports owner insert" on public.imports for insert with check(owner_id=auth.uid());create policy "conflicts read" on public.conflicts for select using(public.can_read_trip(trip_id));create policy "conflicts edit" on public.conflicts for all using(public.can_edit_trip(trip_id)) with check(public.can_edit_trip(trip_id));create policy "booking windows read" on public.booking_windows for select using(public.can_read_trip(trip_id));create policy "booking windows edit" on public.booking_windows for all using(public.can_edit_trip(trip_id)) with check(public.can_edit_trip(trip_id));create policy "audit read" on public.audit_events for select using(public.can_edit_trip(trip_id));
